parameters.jsCode:
const raw = $input.first().json;
const body = raw.body ?? raw;
const pack = body.pack;
if (!pack) throw new Error('Missing pack in webhook body');
const brand = body.brand || pack.brand || 'alpha';
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const d = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
const runId = body.run_id || pack.run_id || `alpha-${d}-${Math.random().toString(36).slice(2, 6)}`;
pack.brand = brand;
pack.run_id = runId;
if (!Array.isArray(pack.x_thread)) {
  pack.x_thread = typeof pack.x_thread === 'string' ? pack.x_thread.split(/\n+/).filter(Boolean) : [];
}
const banned = [/vào long/i, /vào short/i, /entry/i, /\bSL\b/i, /\bTP\b/i, /chắc ăn/i, /guaranteed/i];
const failed = [];
if (banned.some((r) => (pack.telegram_brief || '').match(r) || pack.x_thread.some((t) => String(t).match(r)))) failed.push(1);
for (const t of pack.x_thread) {
  if (String(t).length > 280) failed.push(4);
  if (/https?:\/\//i.test(String(t))) failed.push(4);
}
if ((pack.threads_post || '').length > 500) failed.push(4);
pack.compliance = { status: failed.length ? 'FAIL' : 'PASS', failed_rules: [...new Set(failed)] };
const zernio_account_ids = ['6a0c6dbd5e333c05299f1d12', '6a0c28345e333c05299b981a'];
return [{
  json: {
    brand,
    run_id: runId,
    date: d,
    topic: pack.topic || 'XAUUSD daily brief',
    pack,
    zernio_account_ids,
    status: 'draft_ready',
    created_at: now.toISOString(),
    writer_output_file: `output/alpha/${d}/${runId}.pack.json`,
    source: 'alpha-factory'
  }
}];

